test_suite:
test('starts with empty selectedText', () => {
  const ref = { current: document.createElement('div') };
  const { result } = renderHook(() => useSelection(ref));
  expect(result.current.selectedText).toBe('');
});

test('hasSelection starts false', () => {
  const ref = { current: document.createElement('div') };
  const { result } = renderHook(() => useSelection(ref));
  expect(result.current.hasSelection).toBe(false);
});

test('updates selectedText on selectionchange event', () => {
  const container = document.createElement('div');
  container.textContent = 'Hello World';
  document.body.appendChild(container);
  const ref = { current: container };
  const { result } = renderHook(() => useSelection(ref));

  const selection = window.getSelection()!;
  const range = document.createRange();
  range.selectNodeContents(container);
  selection.removeAllRanges();
  selection.addRange(range);

  act(() => {
    document.dispatchEvent(new Event('selectionchange'));
  });

  expect(result.current.selectedText).toBe('Hello World');
  document.body.removeChild(container);
});

test('clears selectedText when selection removed', () => {
  const container = document.createElement('div');
  container.textContent = 'test';
  document.body.appendChild(container);
  const ref = { current: container };
  const { result } = renderHook(() => useSelection(ref));

  const selection = window.getSelection()!;
  const range = document.createRange();
  range.selectNodeContents(container);
  selection.addRange(range);
  act(() => { document.dispatchEvent(new Event('selectionchange')); });

  selection.removeAllRanges();
  act(() => { document.dispatchEvent(new Event('selectionchange')); });
  expect(result.current.selectedText).toBe('');
  document.body.removeChild(container);
});

// __hidden__
test('hasSelection is true when text is selected', () => {
  const container = document.createElement('p');
  container.textContent = 'select me';
  document.body.appendChild(container);
  const ref = { current: container };
  const { result } = renderHook(() => useSelection(ref));

  const selection = window.getSelection()!;
  const range = document.createRange();
  range.selectNodeContents(container);
  selection.removeAllRanges();
  selection.addRange(range);
  act(() => { document.dispatchEvent(new Event('selectionchange')); });

  expect(result.current.hasSelection).toBe(true);
  document.body.removeChild(container);
});

solution:
import { useState, useEffect, RefObject } from 'react';

export function useSelection(ref: RefObject<HTMLElement | null>) {
  const [selectedText, setSelectedText] = useState('');

  useEffect(() => {
    const handler = () => {
      const selection = window.getSelection();
      if (!selection || !ref.current) {
        setSelectedText('');
        return;
      }
      if (selection.rangeCount === 0) { setSelectedText(''); return; }
      const range = selection.getRangeAt(0);
      if (ref.current.contains(range.commonAncestorContainer)) {
        setSelectedText(selection.toString());
      } else {
        setSelectedText('');
      }
    };
    document.addEventListener('selectionchange', handler);
    return () => document.removeEventListener('selectionchange', handler);
  }, [ref]);

  return { selectedText, hasSelection: selectedText.length > 0 };
}
